1	package world
2	
3	import (
4		"errors"
5		"fmt"
6	)
7	
8	// ConflictError 表示保存与存档当前状态冲突：槽重名、覆盖所依据的
9	// 记录已不是该槽最新记录等。调用方应当重新读取后再决定是否重试。
10	type ConflictError struct {
11		Slot   string
12		Reason string
13	}
14	
15	func (e *ConflictError) Error() string {
16		if e.Slot == "" {
17			return "world: 存档冲突: " + e.Reason
18		}
19		return fmt.Sprintf("world: 存档槽 %q 冲突: %s", e.Slot, e.Reason)
20	}
21	
22	// NotFoundError 表示指定的槽或记录不存在。
23	type NotFoundError struct {
24		Slot   string
25		Record RecordID
26	}
27	
28	func (e *NotFoundError) Error() string {
29		switch {
30		case e.Record != "":
31			return fmt.Sprintf("world: 记录不存在: %s", e.Record)
32		case e.Slot != "":
33			return fmt.Sprintf("world: 存档槽不存在: %q", e.Slot)
34		default:
35			return "world: 槽或记录不存在"
36		}
37	}
38	
39	// CorruptError 表示记录内容损坏：校验和不符、父记录链断裂、
40	// 数据无法解析等。
41	type CorruptError struct {
42		Slot   string
43		Record RecordID
44		Reason string
45	}
46	
47	func (e *CorruptError) Error() string {
48		where := e.Slot
49		if e.Record != "" {
50			if where != "" {
51				where += "/"
52			}
53			where += string(e.Record)
54		}
55		if where == "" {
56			where = "?"
57		}
58		return fmt.Sprintf("world: 记录损坏(%s): %s", where, e.Reason)
59	}
60	
61	// VersionRejectedError 表示记录自身完好，但其规则版本不在调用方
62	// 明确给出的可接受版本集合内。
63	type VersionRejectedError struct {
64		Slot     string
65		Record   RecordID
66		Version  string
67		Accepted []string
68	}
69	
70	func (e *VersionRejectedError) Error() string {
71		return fmt.Sprintf("world: 记录 %s 的规则版本 %q 不在可接受版本集合 %v 内",
72			e.Record, e.Version, e.Accepted)
73	}
74	
75	// ErrUnrecoverable 表示槽中找不到任何一份校验通过且版本可接受的
76	// 历史记录，无法恢复。调用方可用 errors.Is 判断。
77	var ErrUnrecoverable = errors.New("world: 没有可恢复的历史记录")
78	
79	// UnrecoverableError 包装 ErrUnrecoverable 并给出具体原因。
80	type UnrecoverableError struct {
81		Slot   string
82		Reason string
83	}
84	
85	func (e *UnrecoverableError) Error() string {
86		return fmt.Sprintf("world: 槽 %q 不可恢复: %s", e.Slot, e.Reason)
87	}
88	
89	func (e *UnrecoverableError) Unwrap() error { return ErrUnrecoverable }
