48		p := checksumPayload{
49			Format:    e.Format,
50			ID:        e.ID,
51			Parent:    e.Parent,
52			SlotFirst: e.SlotFirst,
53			State:     e.State,
54		}
55		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
56		b, _ := json.Marshal(p)
