81		}
82	
83		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
84		f, err := os.OpenFile(final+".tmp",
85			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
86		if err != nil {
87			return err
88		}
89		tmpName := f.Name()
90		clean := true
91		defer func() {
