1	package world
2	
3	// Rules 是建立世界时必须满足的规则集合。
4	//
5	// Version 是非空的规则版本；Locations 是允许出现的地点；Edges 描述地点
6	// 之间的连通关系（无向，移动可以沿任一方向发生）；ItemKinds 是允许出现
7	// 的物品种类；CarryLimits 给出每个角色可携带物品的总量上限。
8	type Rules struct {
9		Version     string
10		Locations   []string
11		Edges       []Edge
12		ItemKinds   []string
13		CarryLimits map[string]int
14	}
15	
16	// Edge 表示两个地点之间的一条连通关系。
17	type Edge struct {
18		From string
19		To   string
20	}
21	
22	// CharacterItem 是角色携带的一种物品及其数量。
23	type CharacterItem struct {
24		Item  string
25		Count int
26	}
27	
28	// Character 是一个角色：标识、所在地点和携带物品。
29	type Character struct {
30		ID       string
31		Location string
32		Items    []CharacterItem
33	}
34	
35	// State 是某一时刻世界的完整状态。
36	//
37	// Time 是时间片，世界建立时从零开始，只能向前推进。
38	type State struct {
39		Seed       int64
40		Rules      Rules
41		Time       int
42		Characters []Character
43	}
44	
45	// InitialData 是建立世界所需的初始数据。
46	type InitialData struct {
47		// Seed 是整数地图种子。
48		Seed int64
49		// Rules 是非空规则。
50		Rules Rules
51		// Characters 是初始角色集合，角色必须位于规则允许的地点，
52		// 携带的物品必须合法且不超过携带上限。
53		Characters []Character
54	}
55	
56	// Move 要求角色沿一条允许的连通关系移动到另一地点。
57	type Move struct {
58		Character string
59		To        string
60	}
61	
62	// ItemChange 表示某角色持有的某种物品数量变化（Delta 可正可负）。
63	type ItemChange struct {
64		Character string
65		Item      string
66		Delta     int
67	}
68	
69	// Commit 是一次原子提交：若干移动、物品数量变化和一次时间推进。
70	//
71	// Time 是提交后期望到达的绝对时间片，不能早于当前时间片。
72	// 任意一项不合法都会导致整次提交失败，世界保持提交前状态。
73	type Commit struct {
74		Moves       []Move
75		ItemChanges []ItemChange
76		Time        int
77	}
78	
79	func cloneRules(r Rules) Rules {
80		cp := Rules{
81			Version:   r.Version,
82			Locations: append([]string(nil), r.Locations...),
83			Edges:     append([]Edge(nil), r.Edges...),
84			ItemKinds: append([]string(nil), r.ItemKinds...),
85		}
86		if r.CarryLimits != nil {
87			cp.CarryLimits = make(map[string]int, len(r.CarryLimits))
88			for k, v := range r.CarryLimits {
89				cp.CarryLimits[k] = v
90			}
91		}
92		return cp
93	}
94	
95	func cloneCharacters(chars []Character) []Character {
96		if chars == nil {
97			return nil
98		}
99		cp := make([]Character, len(chars))
100		for i, c := range chars {
101			cp[i] = Character{
102				ID:       c.ID,
103				Location: c.Location,
104				Items:    append([]CharacterItem(nil), c.Items...),
105			}
106		}
107		return cp
108	}
109	
110	func cloneState(s State) State {
111		return State{
112			Seed:       s.Seed,
113			Rules:      cloneRules(s.Rules),
114			Time:       s.Time,
115			Characters: cloneCharacters(s.Characters),
116		}
117	}
118

