222		history, err := a.slotHistoryLocked(slot)
223		if err != nil {
224			return Record{}, err
225		}
226	
227		var lastReason string
228		for _, id := range history {
229			env, verifyErr := a.loadAndVerifyLocked(id)
230			if verifyErr != nil {
231				// 文件缺失、无法解析、校验和不符、记录标识不符、父记录关系
232				// 异常或世界状态不自洽：受损记录不能成为恢复结果，越过它
233				// 继续看更早的记录（不读其中的父标识或槽首标记）。
234				lastReason = verifyErr.Error()
235				continue
236			}
237			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
