239				lastReason = (&VersionRejectedError{
240					Record:  id,
241					Version: env.State.Rules.Version,
242				}).Error()
243				continue
244			}
245			return envToRecord(env), nil
246		}
247	
248		if lastReason == "" {
249			lastReason = "槽中没有任何可确认归属的历史记录"
250		}
251		return Record{}, &UnrecoverableError{Slot: slot, Reason: lastReason}
252	}
