749	// 仍报损坏，本次恢复不处理这两种情况。
750	func TestRecoverMissingAndCorruptPointer(t *testing.T) {
751		a, dir := newTestArchive(t)
752		if _, err := a.RecoverLatest("nope", []string{"v1"}); !errors.As(err, new(*NotFoundError)) {
753			t.Fatalf("槽不存在应 NotFound，得到 %T: %v", err, err)
754		}
755		w := baseWorld(t)
756		if _, err := a.Save("s", w); err != nil {
757			t.Fatal(err)
758		}
759		if err := os.WriteFile(filepath.Join(dir, slotsName, "s.json"), []byte("{not json"), 0o600); err != nil {
760			t.Fatal(err)
761		}
762		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.As(err, new(*CorruptError)) {
