455	// writeRawRecord 直接写入一条记录文件并返回其标识，供损坏/版本测试使用。
456	func writeRawRecord(t *testing.T, a *Archive, parent RecordID, first bool, st State) RecordID {
457		t.Helper()
458		id, err := newRecordID()
459		if err != nil {
460			t.Fatal(err)
461		}
462		env := &envelope{
463			Format:    archiveFormatVersion,
464			ID:        id,
465			Parent:    parent,
466			SlotFirst: first,
467			State:     st,
468		}
469		env.Checksum = computeChecksum(env)
470		if err := writeRecord(a.dir, env); err != nil {
471			t.Fatal(err)
472		}
473		return id
474	}
475	
476	// updatePointer 模拟一个遵循磁盘格式的写入器：新记录已完整落盘后原子
477	// 更新槽指针，并把新记录按保存次序前置到历史索引。
478	func updatePointer(t *testing.T, a *Archive, slot string, id RecordID) {
479		t.Helper()
480		lock, err := acquireLock(a.dir)
481		if err != nil {
482			t.Fatal(err)
483		}
484		defer lock.release()
485		old, err := a.readSlotPointerLocked(slot)
486		if err != nil {
487			t.Fatal(err)
488		}
489		history := []RecordID{id}
490		for _, hid := range old.History {
491			if hid != id {
492				history = append(history, hid)
493			}
494		}
495		if err := a.persistSlotPointerLocked(slot, slotPointer{Latest: id, History: history}); err != nil {
496			t.Fatal(err)
497		}
498	}
