// TestConfirmRecoverLegacyPointer 旧格式裸指针下确认恢复仍可工作：确认
// 后指针持有完整历史，新记录排在最前。
func TestConfirmRecoverLegacyPointer(t *testing.T) {
	a, dir := newTestArchive(t)
	ids := saveN(t, a, "s", 2) // r2 r1 r0
	writeLegacyPointer(t, a, "s", ids[0])

