			ga, _ := Open(dir)
			_, err := ga.ConfirmRecover("s", preview.Current, preview.Source, []string{"v1"})
			mu.Lock()
			defer mu.Unlock()
			if err == nil {
				wins++
			} else if isConflict(err) {
				conflicts++
			} else {
